from functools import lru_cache

class Solution:
    def integerReplacement(self, n: int) -> int:
        @lru_cache(None)
        def f(x: int) -> int:
            if x == 1:
                return 0
            if x % 2 == 0:
                return 1 + f(x // 2)
            return 1 + min(f(x + 1), f(x - 1))
        return f(n)

