class Solution {
    unordered_map<unsigned int, int> memo;

    int solve(unsigned int x) {
        if (x == 1) return 0;
        auto it = memo.find(x);
        if (it != memo.end()) return it->second;
        int res = (x % 2 == 0) ? 1 + solve(x / 2)
                               : 1 + min(solve(x + 1), solve(x - 1));
        return memo[x] = res;
    }

public:
    int integerReplacement(int n) {
        memo.clear();
        return solve(n);
    }
};

