import java.util.*;

class Solution {
    private Map<Long, Integer> memo;

    private int solve(long x) {
        if (x == 1) return 0;
        Integer hit = memo.get(x);
        if (hit != null) return hit;
        int res = (x % 2 == 0) ? 1 + solve(x / 2)
                               : 1 + Math.min(solve(x + 1), solve(x - 1));
        memo.put(x, res);
        return res;
    }

    public int integerReplacement(int n) {
        memo = new HashMap<>();
        return solve(n);
    }
}

