var integerReplacement = function(n) {
    const memo = new Map();
    const f = x => {
        if (x === 1) return 0;
        if (memo.has(x)) return memo.get(x);
        const res = x % 2 === 0 ? 1 + f(x / 2)
                                : 1 + Math.min(f(x + 1), f(x - 1));
        memo.set(x, res);
        return res;
    };
    return f(n);
};

