class Solution {
public:
    int integerReplacement(int n) {
        int steps = 0;
        unsigned int x = n;
        while (x != 1) {
            if ((x & 1) == 0) x >>= 1;
            else if (x == 3 || (x & 3) == 1) x--;
            else x++;
            steps++;
        }
        return steps;
    }
};

